/* ==========================================================================
   KUYA DRIVER AI — PRODUCTION AUTOMOTIVE UI & UNIVERSAL PWA STYLESHEET (v6)
   Target: https://esp046-cyber.github.io/Kuya-Driver-AI/
   Designed for iOS Safari, Android Chrome, & In-Car Phone Mounts (320px–1920px+)
   ========================================================================== */

:root {
  /* Core Palette - Light Mode (High-Contrast Daylight Driving) */
  --bg: #EEF2F9;
  --bg-elevated: #F8FAFC;
  --card: #FFFFFF;
  --card-alt: #F1F5F9;
  --ink: #0B1120;
  --ink-secondary: #1E293B;
  --mute: #475569;
  --line: #CBD5E1;
  --line-strong: #94A3B8;

  /* Philippine Flag & Automotive Semantic Accents */
  --blue: #0038A8;
  --blue-bright: #2563EB;
  --blue-glow: rgba(37, 99, 235, 0.18);
  --gold: #FCD116;
  --gold-deep: #EAB308;
  --gold-ink: #0B0F19;
  --red: #CE1126;
  --red-soft: rgba(206, 17, 38, 0.14);
  --ok: #16A34A;
  --ok-bright: #22C55E;
  --ok-soft: rgba(34, 197, 94, 0.16);

  /* Spacing & Sizing Tokens (4px/8px Automotive Scale) */
  --s1: 4px;
  --s2: 8px;
  --s3: 12px;
  --s4: 16px;
  --s5: 20px;
  --s6: 24px;
  --tap: 48px;
  --radius-sm: 10px;
  --radius-md: 16px;
  --radius-lg: 20px;
  --radius-pill: 9999px;

  /* Elevation & Shadows */
  --shadow-sm: 0 2px 6px rgba(11, 17, 32, 0.06);
  --shadow-card: 0 8px 24px -4px rgba(11, 17, 32, 0.08), 0 2px 6px -1px rgba(11, 17, 32, 0.04);
  --shadow-header: 0 4px 20px rgba(0, 24, 72, 0.28);
  --shadow-nav: 0 -6px 24px rgba(0, 0, 0, 0.35);

  color-scheme: light;
  box-sizing: border-box;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

/* System Dark Mode (Auto Night Driving) */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #070B14;
    --bg-elevated: #0D1322;
    --card: #131C31;
    --card-alt: #1A2540;
    --ink: #F8FAFC;
    --ink-secondary: #E2E8F0;
    --mute: #94A3B8;
    --line: #233152;
    --line-strong: #334673;
    --blue-glow: rgba(59, 130, 246, 0.25);
    --ok: #22C55E;
    --shadow-card: 0 10px 28px -6px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.05);
    color-scheme: dark;
  }
}

/* Explicit Dark Mode Toggle */
:root[data-theme="dark"] {
  --bg: #070B14;
  --bg-elevated: #0D1322;
  --card: #131C31;
  --card-alt: #1A2540;
  --ink: #F8FAFC;
  --ink-secondary: #E2E8F0;
  --mute: #94A3B8;
  --line: #233152;
  --line-strong: #334673;
  --blue-glow: rgba(59, 130, 246, 0.25);
  --ok: #22C55E;
  --shadow-card: 0 10px 28px -6px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  color-scheme: dark;
}

/* Car HUD Mode (OLED Anti-Glare, Oversized 64px Touch Targets for Phone Holder) */
body.car {
  --tap: 64px;
  --bg: #000000;
  --bg-elevated: #070B14;
  --card: #0B1120;
  --card-alt: #131C31;
  --ink: #FFFFFF;
  --ink-secondary: #F1F5F9;
  --mute: #A5B4FC;
  --line: #263558;
  --line-strong: #3B82F6;
  --ok: #4ADE80;
  color-scheme: dark;
}

/* ==========================================================================
   1. RESET, SAFE AREAS & SCROLLING ARCHITECTURE (Fixes iOS Safari Clipping)
   ========================================================================== */
*, *::before, *::after {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

[hidden] {
  display: none !important;
}

html {
  min-height: 100%;
  min-height: 100dvh;
  overflow-x: hidden;
  overflow-y: auto;
  scroll-behavior: smooth;
  scroll-padding-top: calc(64px + env(safe-area-inset-top, 0px));
  background-color: var(--bg);
}

body {
  margin: 0;
  min-height: 100dvh;
  background-color: var(--bg);
  background-image:
    radial-gradient(circle at 15% 0%, rgba(0, 56, 168, 0.12), transparent 45%),
    radial-gradient(circle at 85% 100%, rgba(252, 209, 22, 0.06), transparent 45%);
  color: var(--ink);
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  overflow-x: hidden;
  padding-top: env(safe-area-inset-top, 0px);
  padding-bottom: calc(116px + env(safe-area-inset-bottom, 0px));
  -webkit-font-smoothing: antialiased;
}

/* iOS Status Bar / Notch Safe-Area Shield */
body::before {
  content: "";
  position: fixed;
  inset: 0 0 auto 0;
  height: env(safe-area-inset-top, 0px);
  background: linear-gradient(90deg, #002B84 0%, #0038A8 60%, #0A48C4 100%);
  z-index: 100;
}

/* ==========================================================================
   2. STICKY AUTOMOTIVE HEADER (320px - 1920px Zero-Truncation Layout)
   ========================================================================== */
header {
  position: sticky;
  top: env(safe-area-inset-top, 0px);
  z-index: 90;
  background: linear-gradient(135deg, #002E8A 0%, #0038A8 55%, #0D47C1 100%);
  color: #FFFFFF;
  padding: 10px 14px;
  display: flex;
  align-items: center;
  gap: 8px;
  box-shadow: var(--shadow-header);
  border-bottom: 1px solid rgba(255, 255, 255, 0.14);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

header svg {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.25));
}

header h1 {
  font-size: clamp(0.95rem, 3.6vw, 1.15rem);
  font-weight: 800;
  letter-spacing: -0.01em;
  margin: 0;
  flex: 1 1 auto;
  min-width: 0;
  line-height: 1.15;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #FFFFFF;
}

header h1 small {
  display: block;
  font-weight: 500;
  opacity: 0.86;
  font-size: 0.74rem;
  letter-spacing: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-width: 440px) {
  header {
    padding: 8px 10px;
    gap: 6px;
  }
  header svg {
    width: 30px;
    height: 30px;
    flex-basis: 30px;
  }
  header h1 small {
    display: none;
  }
}

.badge {
  font-size: 0.72rem;
  font-weight: 700;
  background: rgba(34, 197, 94, 0.22);
  color: #DCFCE7;
  border: 1px solid rgba(74, 222, 128, 0.45);
  border-radius: var(--radius-pill);
  padding: 4px 9px;
  white-space: nowrap;
  flex: 0 0 auto;
  letter-spacing: 0.02em;
}

.hbtn,
header button.ghost {
  min-height: 36px;
  min-width: 36px;
  padding: 5px 10px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.16);
  border: 1px solid rgba(255, 255, 255, 0.28);
  color: #FFFFFF;
  font-size: 0.78rem;
  font-weight: 700;
  flex: 0 0 auto;
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  box-shadow: none;
}

.hbtn:hover,
header button.ghost:hover {
  background: rgba(255, 255, 255, 0.26);
}

/* ==========================================================================
   3. MAIN CONTAINER & CARD GRID SYSTEM
   ========================================================================== */
main,
#view {
  max-width: 1080px;
  width: 100%;
  margin: 0 auto;
  padding: 16px 14px calc(128px + env(safe-area-inset-bottom, 0px)) !important;
}

/* Physical bottom spacer so fixed bottom nav NEVER cuts off the last card */
main::after,
#view::after {
  content: "";
  display: block;
  width: 100%;
  height: calc(56px + env(safe-area-inset-bottom, 0px));
}

.tab-panel {
  padding-bottom: calc(120px + env(safe-area-inset-bottom, 0px)) !important;
}

h2,
main > h2 {
  font-size: 1.28rem;
  font-weight: 800;
  letter-spacing: -0.015em;
  margin: 6px 0 12px;
  padding-top: 2px;
  color: var(--ink);
  display: flex;
  align-items: center;
  gap: 8px;
}

main > .note {
  margin: 4px 0 14px;
}

.grid {
  display: grid;
  gap: 14px;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 310px), 1fr));
  align-items: start;
}

/* Strict overflow protection for all grid/flex children */
.grid > *,
.row > *,
.two > *,
.card > *,
.hud-grid > *,
.exp > *,
.pit > *,
.sos > *,
.chips > * {
  min-width: 0;
  max-width: 100%;
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  padding: 16px;
  min-width: 0;
  box-shadow: var(--shadow-card);
  position: relative;
  transition: border-color 180ms ease, transform 180ms ease;
}

.card + .card {
  margin-top: 0;
}

.card h3 {
  margin: 0 0 12px;
  font-size: 1.06rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  color: var(--ink);
  display: flex;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--line);
}

/* ==========================================================================
   4. FORMS, INPUTS, SLIDERS & SELECTS
   ========================================================================== */
label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--mute);
  margin: 12px 0 5px;
  letter-spacing: 0.01em;
}

label b {
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  background: var(--card-alt);
  padding: 2px 8px;
  border-radius: 6px;
  border: 1px solid var(--line);
}

input,
select,
textarea {
  width: 100%;
  max-width: 100%;
  min-height: var(--tap);
  font: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: var(--ink);
  background: var(--bg-elevated);
  border: 2px solid var(--line);
  border-radius: 12px;
  padding: 10px 14px;
  transition: border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
  text-overflow: ellipsis;
}

input:focus,
select:focus,
textarea:focus {
  outline: none;
  border-color: var(--blue-bright);
  box-shadow: 0 0 0 4px var(--blue-glow);
  background: var(--card);
}

:root[data-theme="dark"] input:focus,
:root[data-theme="dark"] select:focus,
:root[data-theme="dark"] textarea:focus,
body.car input:focus,
body.car select:focus {
  border-color: var(--gold);
  box-shadow: 0 0 0 3px rgba(252, 209, 22, 0.22);
}

input:invalid {
  border-color: var(--red);
}

/* Custom Range Slider for Traffic Buffer & Car Controls */
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  padding: 0;
  height: 10px;
  min-height: 36px;
  background: transparent;
  border: 0;
  cursor: pointer;
}

input[type="range"]::-webkit-slider-runnable-track {
  height: 10px;
  border-radius: var(--radius-pill);
  background: linear-gradient(90deg, var(--blue) 0%, var(--gold) 100%);
  border: 1px solid var(--line);
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: #FFFFFF;
  border: 3px solid var(--blue);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.35);
  margin-top: -9px;
}

/* ==========================================================================
   5. TACTILE AUTOMOTIVE BUTTONS & CTAs
   ========================================================================== */
button,
.btn {
  min-height: var(--tap);
  min-width: var(--tap);
  max-width: 100%;
  font: inherit;
  font-size: 0.96rem;
  font-weight: 700;
  border: 0;
  border-radius: 12px;
  padding: 10px 16px;
  background: linear-gradient(180deg, #0A48C4 0%, #0038A8 100%);
  color: #FFFFFF;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  text-align: center;
  text-decoration: none;
  box-shadow: 0 3px 10px rgba(0, 56, 168, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.2);
  transition: transform 150ms cubic-bezier(0.2, 0, 0, 1), filter 150ms ease, box-shadow 150ms ease;
  user-select: none;
  -webkit-user-select: none;
}

.btn {
  display: flex;
  width: 100%;
  margin-top: 12px;
  padding: 12px 16px;
  font-size: 1.04rem;
}

button:hover,
.btn:hover {
  filter: brightness(1.08);
}

button:active,
.btn:active {
  transform: scale(0.97);
}

button.gold,
.cta,
.btn.gold {
  background: linear-gradient(180deg, #FFE047 0%, #FCD116 65%, #EAB308 100%);
  color: #0B0F19 !important;
  font-weight: 800;
  box-shadow: 0 4px 14px rgba(252, 209, 22, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.65);
}

.cta {
  min-height: 54px;
  font-size: 1.08rem;
  letter-spacing: -0.01em;
}

button.ghost,
.btn.ghost {
  background: var(--card-alt);
  color: var(--ink);
  border: 1.5px solid var(--line-strong);
  box-shadow: none;
}

button.red,
.btn.red {
  background: linear-gradient(180deg, #E11D48 0%, #CE1126 100%);
  color: #FFFFFF;
  box-shadow: 0 3px 10px rgba(206, 17, 38, 0.28);
}

:focus-visible {
  outline: 3px solid var(--gold);
  outline-offset: 2px;
}

/* ==========================================================================
   6. OUTPUT TOTALS, RESULTS & WINDOW HOURS ROWS (.out & .out.stk)
   ========================================================================== */
.out {
  margin-top: 14px;
  border-top: 2px dashed var(--line);
  padding-top: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.out div {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: baseline;
  gap: 6px 12px;
  padding: 6px 10px;
  border-radius: 10px;
  background: var(--bg-elevated);
  border: 1px solid var(--line);
}

.out div span {
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--mute);
}

.out b,
.num {
  font-variant-numeric: tabular-nums;
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--ink);
  margin-left: auto;
  text-align: right;
}

.out .main {
  background: var(--blue-glow);
  border-color: rgba(59, 130, 246, 0.4);
  padding: 10px 12px;
}

.out .main span {
  color: var(--ink);
  font-weight: 700;
  font-size: 0.94rem;
}

.out .main b {
  color: var(--blue);
  font-size: 1.65rem;
}

body.car .out .main b,
:root[data-theme="dark"] .out .main b {
  color: var(--gold);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .out .main b {
    color: var(--gold);
  }
}

/* Stacked Output Rows (Fixes awkward wrapping on Window Hours & LTO Cards) */
.out.stk div {
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
  gap: 3px;
  margin-bottom: 0;
  padding: 9px 12px;
}

.out.stk div b {
  margin-left: 0;
  text-align: left;
  font-size: 1.05rem;
  line-height: 1.3;
  word-break: break-word;
}

/* ==========================================================================
   7. CHIPS, PILLS, GRIDS & TWO-COLUMN HELPERS
   ========================================================================== */
.row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  align-items: center;
}

.two {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

@media (max-width: 350px) {
  .two {
    grid-template-columns: 1fr;
  }
}

.chips {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  white-space: nowrap;
  gap: 8px;
  margin: 10px 0 6px;
  padding: 2px 2px 8px;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}

.chips::-webkit-scrollbar {
  display: none;
}

.chips > * {
  flex: 0 0 auto;
  max-width: none;
}

.pill,
.chips .pill {
  background: var(--card-alt);
  color: var(--ink);
  border: 1.5px solid var(--line-strong);
  min-height: 40px;
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  font-size: 0.86rem;
  font-weight: 700;
  box-shadow: var(--shadow-sm);
}

:root[data-theme="dark"] .chips .pill,
body.car .chips .pill {
  background: #1E293B;
  color: #F8FAFC;
  border-color: #3B82F6;
}

.chips .pill:active {
  background: var(--gold);
  color: #0B0F19;
  border-color: var(--gold);
}

.op {
  background: var(--gold);
  color: #0B0F19;
  width: var(--tap);
}

/* ==========================================================================
   8. CAR HUD DASHBOARD, SPEEDOMETER & PIT-STOP CARDS
   ========================================================================== */
.hud-grid {
  display: grid;
  gap: 14px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

@media (orientation: portrait) and (max-width: 640px) {
  .hud-grid {
    grid-template-columns: 1fr;
  }
}

.big {
  font-size: clamp(2.4rem, 8vw, 3.5rem);
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  line-height: 1.05;
  letter-spacing: -0.03em;
  color: var(--ink);
  margin: 4px 0;
}

body.car .big,
:root[data-theme="dark"] .big {
  color: var(--gold);
  text-shadow: 0 0 24px rgba(252, 209, 22, 0.2);
}

.exp {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 6px;
}

.exp button {
  min-height: 68px;
  font-size: 1.02rem;
  font-weight: 800;
  border-radius: 14px;
}

.pit,
.sos {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.pit a,
.sos a {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 6px;
  min-height: 96px;
  padding: 14px;
  border-radius: 14px;
  background: var(--card);
  border: 1.5px solid var(--line);
  color: var(--ink);
  text-decoration: none;
  font-weight: 700;
  font-size: 0.9rem;
  line-height: 1.25;
  box-shadow: var(--shadow-card);
  transition: transform 150ms ease, border-color 150ms ease;
}

.pit a:active,
.sos a:active {
  transform: scale(0.97);
  border-color: var(--gold);
}

.pit .ic,
.sos .ic {
  font-size: 1.65rem;
  line-height: 1;
}

.sos a.call {
  border-color: rgba(206, 17, 38, 0.65);
  background: linear-gradient(160deg, var(--card) 60%, rgba(206, 17, 38, 0.12) 100%);
}

.sos a b {
  font-size: 1.12rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--gold);
}

:root[data-theme="light"] .sos a b {
  color: var(--red);
}

.sos a small {
  font-weight: 500;
  color: var(--mute);
  font-size: 0.76rem;
}

/* ==========================================================================
   9. CODING & SOS TAB: MMDA BANNER, RFID WALLETS & PMS PROGRESS BAR
   ========================================================================== */
.status {
  font-weight: 800;
  padding: 10px 14px;
  border-radius: 12px;
  margin-top: 10px;
}

.status.no {
  background: var(--red);
  color: #FFFFFF;
}

.status.yes {
  background: #22C55E;
  color: #04210F;
}

.codeban {
  font-size: 1.18rem;
  font-weight: 900;
  padding: 16px;
  border-radius: 14px;
  text-align: center;
  background: var(--bg-elevated);
  border: 2px solid var(--line);
  line-height: 1.25;
  margin: 10px 0;
  box-shadow: var(--shadow-sm);
}

.codeban small {
  display: block;
  font-size: 0.86rem;
  font-weight: 600;
  margin-top: 6px;
  opacity: 0.92;
}

.codeban.yes {
  background: linear-gradient(135deg, #16A34A 0%, #22C55E 100%);
  color: #031B0C;
  border-color: #4ADE80;
}

.codeban.no {
  background: linear-gradient(135deg, #B91C1C 0%, #CE1126 100%);
  color: #FFFFFF;
  border-color: #F87171;
}

/* Autosweep & Easytrip RFID Wallets */
.wal {
  background: var(--bg-elevated);
  border: 2px solid var(--line);
  border-radius: 14px;
  padding: 12px;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.wal.low {
  border-color: var(--red);
  box-shadow: 0 0 0 3px var(--red-soft);
}

.wal input {
  font-size: 1.28rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  text-align: center;
  padding: 8px 6px;
}

.stack {
  display: grid;
  gap: 6px;
  margin-top: 8px;
}

.stack button {
  width: 100%;
  min-height: 40px;
  font-size: 0.84rem;
  padding: 6px 8px;
  border-radius: 10px;
}

.alert {
  margin-top: 8px;
  background: var(--red);
  color: #FFFFFF;
  font-weight: 700;
  font-size: 0.8rem;
  padding: 8px 10px;
  border-radius: 10px;
  line-height: 1.3;
  text-align: center;
}

/* Oil Change / PMS Progress Bar */
.bar {
  height: 16px;
  border-radius: var(--radius-pill);
  background: var(--bg-elevated);
  border: 1px solid var(--line);
  overflow: hidden;
  margin: 10px 0 6px;
}

.bar i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #16A34A, #22C55E);
  border-radius: var(--radius-pill);
  transition: width 250ms ease;
}

.bar.gold i {
  background: linear-gradient(90deg, #EAB308, #FCD116);
}

.bar.red i {
  background: linear-gradient(90deg, #B91C1C, #EF4444);
}

/* ==========================================================================
   10. FIXED BOTTOM NAVIGATION BAR & DESKTOP SIDEBAR
   ========================================================================== */
nav {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  background: #080E1E !important;
  border-top: 1px solid #263558 !important;
  display: flex;
  padding-bottom: env(safe-area-inset-bottom, 0px);
  z-index: 95;
  box-shadow: var(--shadow-nav);
}

nav button {
  flex: 1 1 0%;
  min-width: 0;
  min-height: 62px;
  background: transparent !important;
  color: #94A3B8;
  border-radius: 0;
  padding: 8px 4px;
  font-size: 0.74rem;
  font-weight: 600;
  line-height: 1.15;
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: center;
  justify-content: center;
  text-align: center;
  box-shadow: none !important;
}

nav button:hover {
  color: #E2E8F0;
  filter: none;
}

nav button[aria-current="page"],
nav button[aria-current=page] {
  color: #FCD116 !important;
  font-weight: 800;
  background: rgba(252, 209, 22, 0.08) !important;
  box-shadow: inset 0 3px 0 #FCD116 !important;
}

@media (min-width: 900px) {
  body {
    padding-bottom: 0;
    padding-left: 170px;
  }
  main,
  #view {
    padding: 24px 28px 48px !important;
  }
  main::after,
  #view::after {
    height: 24px;
  }
  nav {
    top: 0;
    right: auto;
    width: 170px;
    flex-direction: column;
    justify-content: flex-start;
    border-top: 0 !important;
    border-right: 1px solid #263558 !important;
    padding-top: 76px;
  }
  nav button {
    flex: 0 0 auto;
    min-height: 68px;
    font-size: 0.85rem;
    padding: 12px 10px;
  }
  nav button[aria-current="page"],
  nav button[aria-current=page] {
    box-shadow: inset 4px 0 0 #FCD116 !important;
  }
}

/* ==========================================================================
   11. UTILITIES, TOAST NOTIFICATIONS & REDUCED MOTION
   ========================================================================== */
.empty {
  color: var(--mute);
  padding: 18px;
  border: 2px dashed var(--line);
  border-radius: 14px;
  text-align: center;
  font-size: 0.9rem;
}

.note {
  color: var(--mute);
  font-size: 0.82rem;
  line-height: 1.4;
  margin: 8px 0 0;
}

.ellip {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

canvas {
  max-width: 100%;
  height: auto;
  border-radius: 12px;
  background: #0B0F19;
}

#toast {
  position: fixed;
  left: 50%;
  bottom: calc(82px + env(safe-area-inset-bottom, 0px));
  transform: translateX(-50%) translateY(10px);
  background: #FCD116;
  color: #0B0F19;
  font-weight: 800;
  font-size: 0.88rem;
  padding: 10px 18px;
  border-radius: var(--radius-pill);
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.45);
  opacity: 0;
  pointer-events: none;
  transition: opacity 180ms ease, transform 180ms ease;
  z-index: 120;
  max-width: 92%;
  text-align: center;
}

#toast.on {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition: none !important;
    animation: none !important;
    scroll-behavior: auto !important;
  }
}

